import type { CSSProperties } from "react";

// Generated by strokit. Colors follow --sk-stroke; prefers-reduced-motion shows the final frame.
const css = `
.sk-zz0kxu-0 {
  stroke: var(--sk-stroke, #111111);
  stroke-dasharray: 1 1;
  animation: sk-zz0kxu-t0-draw calc(2200ms / var(--sk-speed, 1)) ease-in-out 0ms var(--sk-iterations, infinite) alternate both;
  animation-play-state: var(--sk-play-state, running);
}
@keyframes sk-zz0kxu-t0-draw {
  0% {
    stroke-dashoffset: 1;
  }
  100% {
    stroke-dashoffset: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .sk-zz0kxu * {
    animation: none;
  }
  .sk-zz0kxu-0 {
    stroke-dashoffset: 0;
  }
}
`;

export type AssinaturaDrawProps = {
  /** Width and height (number = px). Defaults to the SVG's own size. */
  size?: number | string;
  /** Playback speed multiplier: 2 plays twice as fast. */
  speed?: number;
  /** true repeats forever, false plays once. Defaults to the exported animation. */
  loop?: boolean;
  paused?: boolean;
  className?: string;
  /** Accessible name. Defaults to "Assinatura". */
  label?: string;
};

export function AssinaturaDraw({
  size,
  speed = 1,
  loop,
  paused = false,
  className,
  label = "Assinatura",
}: AssinaturaDrawProps) {
  const style = {
    "--sk-speed": speed,
    "--sk-play-state": paused ? "paused" : "running",
    ...(loop === undefined ? {} : { "--sk-iterations": loop ? "infinite" : 1 }),
  } as CSSProperties;

  return (
    <svg
      viewBox="0 0 240 120"
      width={size ?? 240}
      height={size ?? 120}
      className={className ? `sk-zz0kxu ${className}` : "sk-zz0kxu"}
      style={style}
      role="img"
      aria-label={label}
    >
      <style>{css}</style>
      <title>{"Assinatura"}</title>
      <path d="M16 84 C 34 30, 58 18, 62 40 C 66 62, 40 92, 34 76 C 28 60, 70 48, 92 62 C 110 74, 104 90, 96 84 C 88 78, 112 50, 130 58 C 146 66, 134 88, 144 86 C 156 84, 162 56, 176 60 C 190 64, 180 86, 194 84 C 206 82, 214 66, 226 62" fill="none" stroke="#111111" strokeWidth="5" strokeLinecap="round" strokeLinejoin="round" pathLength="1" className="sk-zz0kxu-0" />
      <path d="M40 100 H 210" fill="none" stroke="#111111" strokeWidth="3" strokeLinecap="round" pathLength="1" className="sk-zz0kxu-0" />
    </svg>
  );
}
